import{_ as t,o,c as a,ah as s}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Déploiement","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/deployment.md","filePath":"src/guide/deployment.md"}'),d={name:"guide/deployment.md"};function r(n,e,i,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="deploiement" tabindex="-1">Déploiement <a class="header-anchor" href="#deploiement" aria-label="Permalink to &quot;Déploiement&quot;">​</a></h1><p>La production tourne sur le <strong>cPanel d&#39;edPage</strong>, à côté de Naia et du site NextBoxx (ADR-007). Le serveur n&#39;a ni Composer ni Node : les dépendances et les assets sont construits dans GitHub Actions, puis envoyés avec la version.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>URL</td><td><code>https://kura.nextboxx.net</code></td></tr><tr><td>Serveur</td><td>cPanel d&#39;edPage, Apache, AutoSSL</td></tr><tr><td>PHP</td><td>8.3 (MultiPHP), extensions <code>pdo_mysql</code>, <code>mbstring</code>, <code>openssl</code>, <code>sodium</code>, <code>dom</code>, <code>xmlreader</code>, <code>fileinfo</code>, <code>zip</code>, <code>gd</code></td></tr><tr><td>Base</td><td>MySQL, base et utilisateur préfixés par le compte cPanel</td></tr><tr><td>Déploiement</td><td>GitHub Actions → <strong>Deploy to cPanel</strong>, lancé à la main</td></tr><tr><td>Scripts</td><td><code>deploy/cpanel/</code> du dépôt <code>kura-web</code></td></tr></tbody></table><h2 id="ce-que-fait-un-deploiement" tabindex="-1">Ce que fait un déploiement <a class="header-anchor" href="#ce-que-fait-un-deploiement" aria-label="Permalink to &quot;Ce que fait un déploiement&quot;">​</a></h2><ol><li><strong>Build</strong> : le workflow refuse un commit dont la CI <code>lint-test</code> n&#39;est pas verte, sauf si l&#39;option <code>force</code> est cochée. Il compile les assets (<code>pnpm build</code>) et installe les dépendances PHP de production (<code>composer install --no-dev</code>).</li><li><strong>Envoi</strong> : rsync de la version vers le compte. Ne sont <strong>jamais</strong> touchés : <code>.env</code>, les clés OAuth (<code>storage/oauth-*.key</code>), <code>storage/app</code> (pièces de candidature, conventions, factures, sauvegardes), <code>storage/logs</code>, <code>storage/framework</code>, le lien <code>public/storage</code>, ni ce que cPanel dépose (<code>.htaccess</code> racine, <code>.well-known</code>, <code>cgi-bin</code>, <code>error_log</code>). Le workflow réinscrit dans <code>public/.htaccess</code> la version de PHP du sous-domaine, sans quoi Apache retomberait sur PHP 8.2 et Kura ne démarrerait pas.</li><li><strong><code>deploy.sh</code></strong> : <code>package:discover</code>, vérification des clés OAuth, sauvegarde de la base (<code>storage/app/backups/db-*.sql.gz</code>, les 10 dernières conservées), mise en maintenance, migrations, <code>RoleSeeder</code>, caches, redémarrage de la file, pose des crons au premier déploiement, remise en ligne.</li><li><strong>Vérification</strong> : <code>GET /up</code> doit répondre <code>200</code>.</li></ol><p>Un déploiement qui échoue après la mise en maintenance <strong>laisse le site en maintenance</strong>. C&#39;est volontaire : mieux vaut un site fermé qu&#39;une base à moitié migrée. Corriger, puis relancer le déploiement, qui remet le site en ligne.</p><h2 id="premiere-installation" tabindex="-1">Première installation <a class="header-anchor" href="#premiere-installation" aria-label="Permalink to &quot;Première installation&quot;">​</a></h2><h3 id="dans-cpanel" tabindex="-1">Dans cPanel <a class="header-anchor" href="#dans-cpanel" aria-label="Permalink to &quot;Dans cPanel&quot;">​</a></h3><ol><li><strong>Domains</strong> : créer le sous-domaine avec pour racine web le dossier <code>public</code> de l&#39;application (<code>/home/&lt;compte&gt;/kura.nextboxx.net/public</code>). Si la racine pointe sur le dossier de l&#39;application, le <code>.env</code> et les clés OAuth sont exposés.</li><li><strong>MultiPHP Manager</strong> : PHP 8.3 pour le sous-domaine. Pour changer de version plus tard, modifier ici <strong>et</strong> <code>CPANEL_PHP_BIN</code>, puis redéployer : le déploiement réécrit le réglage.</li><li><strong>PHP Extensions</strong> : activer les extensions du tableau ci-dessus (<code>dom</code> et <code>gd</code> servent aux PDF, <code>zip</code> et <code>xmlreader</code> aux imports et exports de tableurs).</li><li><strong>MySQL Databases</strong> : une base et son utilisateur, avec tous les droits.</li><li><strong>Email Accounts</strong> : l&#39;adresse d&#39;envoi (par exemple <code>kura@nextboxx.net</code>).</li><li><strong>SSH Access</strong> : générer une clé dédiée sur un poste (<code>ssh-keygen -t ed25519 -C kura-deploy -f kura-deploy</code>), importer la clé publique dans cPanel, puis supprimer la clé privée du poste une fois copiée dans GitHub.</li></ol><h3 id="dans-github" tabindex="-1">Dans GitHub <a class="header-anchor" href="#dans-github" aria-label="Permalink to &quot;Dans GitHub&quot;">​</a></h3><p>Dans <code>kura-web</code> → <strong>Settings → Environments → <code>production</code></strong> :</p><table tabindex="0"><thead><tr><th>Secret</th><th>Contenu</th></tr></thead><tbody><tr><td><code>CPANEL_SSH_KEY</code></td><td>Clé privée SSH de déploiement</td></tr><tr><td><code>CPANEL_HOST</code>, <code>CPANEL_PORT</code>, <code>CPANEL_USER</code></td><td>Accès SSH au compte (<code>server.sedver.com</code>, <code>22</code>, le compte cPanel)</td></tr><tr><td><code>CPANEL_APP_PATH</code></td><td>Dossier de l&#39;application, par exemple <code>/home/&lt;compte&gt;/kura.nextboxx.net</code></td></tr><tr><td><code>CPANEL_PHP_BIN</code></td><td><code>/opt/cpanel/ea-php83/root/usr/bin/php</code></td></tr><tr><td><code>KURA_ENV_FILE</code></td><td>Le <code>.env</code> complet, écrit depuis <code>deploy/cpanel/.env.production.example</code>, avec <code>APP_KEY</code> vide. Ne sert qu&#39;à l&#39;installation</td></tr></tbody></table><p>Dans <code>KURA_ENV_FILE</code>, <code>NEXTBOXX_SITE_API_KEY</code> doit valoir exactement le <code>KURA_SITE_API_KEY</code> configuré sur le site NextBoxx. Vide, Kura refuse tous les appels du site. <code>SEVE_*</code> et <code>WHATSAPP_*</code> peuvent rester vides au départ.</p><h3 id="lancer-l-installation" tabindex="-1">Lancer l&#39;installation <a class="header-anchor" href="#lancer-l-installation" aria-label="Permalink to &quot;Lancer l&#39;installation&quot;">​</a></h3><p>Actions → <strong>Deploy to cPanel</strong>, <code>ref</code> = <code>master</code>, <strong>install</strong> coché. <code>install.sh</code> :</p><ul><li>refuse si PHP est introuvable, si la version n&#39;a pas de <code>vendor/</code>, si le serveur a déjà un <code>.env</code>, ou s&#39;il manque l&#39;URL, la base, son mot de passe ou l&#39;adresse d&#39;expéditeur ;</li><li>écrit le <code>.env</code> (droits <code>600</code>), génère <code>APP_KEY</code> et les clés OAuth ;</li><li>lance <code>deploy.sh</code>, sans sauvegarde puisque la base est vide.</li></ul><h3 id="apres-l-installation" tabindex="-1">Après l&#39;installation <a class="header-anchor" href="#apres-l-installation" aria-label="Permalink to &quot;Après l&#39;installation&quot;">​</a></h3><ol><li><p>Créer le premier administrateur, dans le dossier de l&#39;application :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users:create-admin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;nom&gt;&quot;</span></span></code></pre></div><p>Le mot de passe est demandé à l&#39;écran, jamais passé en argument. Le compte est vérifié et porte le rôle Administrateur.</p></li><li><p><strong>Copier en lieu sûr</strong> le <code>.env</code> du serveur et <code>storage/oauth-*.key</code>. Perdre <code>APP_KEY</code> rend illisibles les données chiffrées (secrets 2FA, jobs en file). Perdre ou remplacer les clés OAuth déconnecte tous les utilisateurs de Sève et invalide les jetons émis.</p></li><li><p>Supprimer le secret <code>KURA_ENV_FILE</code>, désormais inutile : le <code>.env</code> vit sur le serveur.</p></li></ol><h2 id="brancher-seve-et-whatsapp" tabindex="-1">Brancher Sève et WhatsApp <a class="header-anchor" href="#brancher-seve-et-whatsapp" aria-label="Permalink to &quot;Brancher Sève et WhatsApp&quot;">​</a></h2><p>Une instance garde son <code>.env</code>, que le déploiement ne réécrit jamais. Une clé se renseigne donc à la main dans le <code>.env</code> du serveur (cPanel › File Manager) ; le déploiement suivant la prend en compte, ou <code>php artisan optimize</code> immédiatement.</p><ul><li><strong>Sève</strong> : tant que <code>SEVE_URL</code> ou <code>SEVE_WS_TOKEN</code> est vide, rien ne part ; les changements attendent dans la file et partent dès que les deux sont renseignés. Une fois <code>SEVE_URL</code> posé, <code>php artisan seve:client</code> crée le client OAuth de Sève et affiche le secret à saisir dans l&#39;émetteur OAuth 2 de Moodle.</li><li><strong>WhatsApp</strong> : <code>WHATSAPP_TOKEN</code> et <code>WHATSAPP_PHONE_NUMBER_ID</code> vides, les messages partent uniquement par email.</li></ul><h2 id="crons" tabindex="-1">Crons <a class="header-anchor" href="#crons" aria-label="Permalink to &quot;Crons&quot;">​</a></h2><p>Posés par <code>deploy.sh</code> au premier déploiement. À défaut, à ajouter dans cPanel (Cron Jobs) à partir de <code>deploy/cpanel/crontab.example</code> :</p><table tabindex="0"><thead><tr><th>Tâche</th><th>Fréquence</th><th>Rôle</th></tr></thead><tbody><tr><td><code>schedule:run</code></td><td>Chaque minute</td><td>Déclenche toutes les tâches planifiées</td></tr><tr><td><code>queue:work --stop-when-empty --max-time=55 --tries=3</code></td><td>Chaque minute</td><td>Envoie notifications, emails et jobs</td></tr><tr><td>Vidage des journaux de cron</td><td>Hebdomadaire</td><td>Évite de saturer le disque</td></tr></tbody></table><p>Sans <code>schedule:run</code>, aucune tâche planifiée ne tourne : ni synchronisation Sève, ni facturation, ni relances, ni passages de cohorte. Sans le worker, aucune notification ne part, <strong>sans erreur visible</strong>.</p><h2 id="operations-courantes" tabindex="-1">Opérations courantes <a class="header-anchor" href="#operations-courantes" aria-label="Permalink to &quot;Opérations courantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Besoin</th><th>Procédure</th></tr></thead><tbody><tr><td>Déployer</td><td>Actions → <strong>Deploy to cPanel</strong>, <code>ref</code> = <code>master</code> (ou une branche, un tag, un commit), <strong>install</strong> décoché</td></tr><tr><td>Un email n&#39;arrive pas</td><td><code>storage/logs/cron-queue.log</code>, puis <code>php artisan queue:failed</code>, corriger, <code>php artisan queue:retry all</code></td></tr><tr><td>Restaurer une sauvegarde</td><td><code>php artisan down</code>, puis <code>gunzip -c storage/app/backups/db-….sql.gz | mysql &lt;base&gt;</code> avec les identifiants du <code>.env</code></td></tr><tr><td>Connaître la version en ligne</td><td><code>storage/app/release.json</code> (branche, commit, date)</td></tr><tr><td>Lire les journaux</td><td><code>storage/logs/laravel-AAAA-MM-JJ.log</code></td></tr></tbody></table><h2 id="bonnes-pratiques" tabindex="-1">Bonnes pratiques <a class="header-anchor" href="#bonnes-pratiques" aria-label="Permalink to &quot;Bonnes pratiques&quot;">​</a></h2><ul><li><strong>Ne jamais modifier le code à la main sur le serveur</strong> : le prochain déploiement écraserait la modification. Seul le <code>.env</code> se modifie sur place.</li><li><strong>Sauvegarder avant toute migration risquée</strong> : le déploiement le fait, mais une opération manuelle mérite sa propre sauvegarde.</li><li><strong>Tester la restauration</strong> : une sauvegarde jamais restaurée n&#39;est pas une sauvegarde.</li><li><strong>Surveiller <code>/up</code></strong> après chaque déploiement, puis les files et les journaux dans l&#39;heure qui suit.</li><li><strong>Ne pas versionner les secrets</strong> : <code>.env</code>, clés OAuth et clés d&#39;API vivent dans l&#39;environnement GitHub ou sur le serveur, jamais dans le dépôt.</li></ul><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="/kura-guide/guide/development.html">Développement</a> pour les commandes et la qualité.</li><li><a href="/kura-guide/guide/integrations.html">Intégrations</a> pour Sève, WhatsApp et les commandes planifiées.</li></ul>',31)])])}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
